import{_ as d,h as n,i as o,c,v as t,p,x as a,m as E,e as i,S as l}from"./chunks/framework.Dvtg8yj2.js";const k=JSON.parse('{"title":"停用词与 stop sequences","description":"","frontmatter":{"title":"停用词与 stop sequences","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/stop-sequences.md","filePath":"llm/stop-sequences.md","lastUpdated":1788454257000}'),r={name:"llm/stop-sequences.md"};function h(m,e,A,B,_,u){const s=n("Mermaid");return o(),c("div",null,[e[1]||(e[1]=t('<h1 id="停用词与-stop-sequences" tabindex="-1">停用词与 stop sequences <a class="header-anchor" href="#停用词与-stop-sequences" aria-label="Permalink to &quot;停用词与 stop sequences&quot;">​</a></h1><div class="epigraph"><p>生成侧的停止条件是字符串或 token 序列上的匹配，不是检索里那张高频虚词表；二者都叫 stop，切断的是完全不同的管道。</p><footer>—— 开放 API 的 stop / eos_token_id 约定；检索停用词见经典 IR 教材，不要混进解码器</footer></div><p>「停用」在两个社区里指两件事情。信息检索的停用词（stop words）是索引前丢掉的高频虚词，为的是倒排表更短、相似度不被 <code>的</code> 与 <code>the</code> 主导。语言模型解码器的 stop sequences 是生成过程中的终止模式：一旦已写出的文本匹配到某条字符串或某个特殊 token，本轮解码结束，匹配片段通常不交给用户。OpenAI 兼容接口的 <code>stop</code>、聊天模板里的 <code>&lt;|eot_id|&gt;</code>、代码补全里的 <code>\\n\\n</code>，都属于后者。混用会导致「把虚词从词表里禁掉」这种无效实现，或「模型不停地写下去直到 max tokens」这种产品事故。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自回归没有内建的句子边界。训练里 EOS 或对话结束符被当成普通 token 学到，推理时只有当采样抽到它、或外部规则判定匹配，序列才停。只靠 EOS 不够：补全代码时要在函数结束处停，不一定抽到 EOS；聊天里模型可能在角色轮次结束后继续扮演用户；工具调用要在结束标签处切开，把后面的胡话丢掉。Stop sequences 把这些边界从「希望模型学会」改成「解码器强制执行」。</p><p>匹配必须定义在哪一层。Token 级匹配快，但对不齐分词：用户写的 stop 字符串 <code>}\\n</code> 可能对应一个 token，也可能对应 <code>}</code> 与 <code>\\n</code> 两个，还可能与前后字节粘在一起。字符串级匹配在解码后的 UTF-8 上做，跨 token 边界仍然正确，却要处理流式：最后一个 token 可能只是停用串的真前缀，不能立刻把这块增量交给客户端，否则用户会看见闪一下又被撤回的 <code>&lt;/</code>。检索停用词完全不在这条链上——那些词往往正是语法骨架，从支撑里禁掉会把句子打成碎片。</p><h3 id="结束符、停用串、与最大长度" tabindex="-1">结束符、停用串、与最大长度 <a class="header-anchor" href="#结束符、停用串、与最大长度" aria-label="Permalink to &quot;结束符、停用串、与最大长度&quot;">​</a></h3><p>三条终止条件同时存在：抽到 EOS / 对话结束 token；已解码文本命中 <code>stop</code> 列表中的某一条；达到 <code>max_tokens</code>。前两条是内容边界，第三条是预算边界。预算触发时序列在语言学上并未结束，调用方看到的是截断，不是完整话语。把截断当 EOS 再送进多轮历史，下一轮会在半句话后续写。实现应分别返回 <code>finish_reason</code>：<code>stop</code>、<code>eos</code>、<code>length</code>，而不是一律叫 finished。</p><p><span class="marginnote">聊天模板规定的结束符是模型词表里的特殊 token，通常应放进 <code>eos_token_id</code> 集合，而不是只当普通 stop 字符串。只做字符串匹配会漏掉「同一逻辑结束、不同表面编码」的情况，也会在流式里多缓存无用尾巴。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Token 级：维护一个结束 id 集合，每步采样后若 `y_t\\in S_{\\mathrm{eos}}$ 则停，该 token 默认不进入可见输出。多 id 结束在对话模型里很常见，系统、用户、助手各有一个结束符，解码助手轮时应把用户开始符也视为 stop，以免模型把下一轮用户的话写完。</p><p>字符串级：在累计解码文本 \\(s\\) 上对每个模式 \\(p\\) 检查 \\(p\\) 是否为 \\(s\\) 的后缀（或是否在本步新增长的窗口内首次出现）。命中后从 \\(s\\) 中裁掉 \\(p\\) 及其右侧。为支持跨 token，缓存尚未提交的尾部：若存在某个 \\(p\\) 以当前未提交串为真前缀，则这段增量对客户端挂起，直到后续 token 证明匹配失败或匹配成功。这与 SSE 取消不是同一件事：取消是调用方中止；stop 是模型输出触达了约定边界，见流式接口的结束语义。</p><p>词表禁令（bad words）把某些 token 的 logit 置 \\(-\\infty\\)，每步都生效，序列不必结束。它更接近约束解码的掩码，而不是 stop。把停用词表当 bad words 喂给聊天模型，等于禁止虚词，语言会崩。Stop 是 <em>终止</em>，bad words 是 <em>禁止出现</em>；产品文档必须分开。</p><h3 id="与约束、采样截断的接合" tabindex="-1">与约束、采样截断的接合 <a class="header-anchor" href="#与约束、采样截断的接合" aria-label="Permalink to &quot;与约束、采样截断的接合&quot;">​</a></h3><p>文法约束保证结构合法，不保证在合法结构结束时停下。JSON 对象已经闭合后，无约束模型仍可能继续写注释。Stop 列表里放 <code>}\\n\\n</code> 或依赖 schema 自动机进入接受态后的强制 EOS，是两种收尾。前者对自由文本补全友好，后者对严格 schema 友好。Nucleus 与 min-\\(p\\) 改变的是下一步支撑，不改变匹配规则；但截断若把 EOS 概率切掉，模型会更常撞上 <code>max_tokens</code>。实现若允许 <code>stop</code> 与 EOS 同时存在，截断应把结束符留在支撑里，或显式降低「切掉 EOS」的概率。</p>',15)),(o(),p(l,null,{default:a(()=>[i(s,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAMP%5B%22%E9%87%87%E6%A0%B7%E4%B8%8B%E4%B8%80%E4%B8%AA%20token%22%5D%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E7%B4%AF%E8%AE%A1%E5%AD%97%E7%AC%A6%E4%B8%B2%22%5D%0A%20%20SAMP%20--%3E%20EOS%7B%22id%20%E2%88%88%20eos%20%E9%9B%86%E5%90%88%3F%22%7D%0A%20%20EOS%20--%3E%7C%E6%98%AF%7C%20STOP%5B%22%E7%BB%93%E6%9D%9F%EF%BC%9Afinish%3Deos%22%5D%0A%20%20DEC%20--%3E%20STR%7B%22%E5%90%8E%E7%BC%80%E5%91%BD%E4%B8%AD%20stop%20%E4%B8%B2%3F%22%7D%0A%20%20STR%20--%3E%7C%E6%98%AF%7C%20CUT%5B%22%E8%A3%81%E6%8E%89%E5%8C%B9%E9%85%8D%E6%AE%B5%EF%BC%8Cfinish%3Dstop%22%5D%0A%20%20STR%20--%3E%7C%E5%90%A6%EF%BC%8C%E4%BD%86%E6%98%AF%E6%9F%90%E6%A8%A1%E5%BC%8F%E7%9A%84%E7%9C%9F%E5%89%8D%E7%BC%80%7C%20HOLD%5B%22%E6%8C%82%E8%B5%B7%E6%B5%81%E5%BC%8F%E5%A2%9E%E9%87%8F%22%5D%0A%20%20STR%20--%3E%7C%E5%90%A6%EF%BC%8C%E4%B8%94%E9%9D%9E%E5%89%8D%E7%BC%80%7C%20EMIT%5B%22%E5%90%91%E5%AE%A2%E6%88%B7%E7%AB%AF%E6%8F%90%E4%BA%A4%E5%A2%9E%E9%87%8F%22%5D%0A%20%20SAMP%20--%3E%20LEN%7B%22%E8%BE%BE%E5%88%B0%20max_tokens%3F%22%7D%0A%20%20LEN%20--%3E%7C%E6%98%AF%7C%20TRUNC%5B%22%E7%BB%93%E6%9D%9F%EF%BC%9Afinish%3Dlength%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>强制停止改变的是序列的长度分布，不是条件 token 分布本身：在停止之前，每步仍按采样器从 \\(p(\\cdot\\mid x_{&lt;t})\\) 抽取。它把「何时结束」从模型内部的 EOS 决策，部分外置到字符串协议。好处是协议可以由产品定义（XML 标签、Markdown 围栏、工具调用括号），不必为每种边界微调模型。坏处是模型不知道你要在这里停，它可能把停用串当成普通内容的一部分来规划；若停用串在训练里很少作为真正的结束，模型会在停之前写出半截结构。</p><p>流式挂起是正确性要求，不是优化。设 stop 为 <code>&lt;/script&gt;</code>，当前尾巴是 <code>&lt;/scr</code>。若先把 <code>&lt;/scr</code> 发给前端再撤回，XSS 过滤与打字机 UI 都会闪错。算法是：对每个模式维护 KMP 失败函数或简单的「当前匹配长度」，只释放不可能成为任一模式前缀的确定前缀。模式很多、且包含彼此前缀时，挂起窗口会变长，首 token 延迟不变，但可见延迟变差。这是 stop 列表过长的真正成本，不是匹配本身的 CPU。</p><p><span class="marginnote">包含空字符串或纯空白的 stop 会立即命中或永不命中，取决于是否 trim。实现应拒绝空模式。只含 <code>\\n</code> 的 stop 在散文里极容易误触发，更适合代码补全。</span></p><h3 id="检索停用词为什么不能搬进解码" tabindex="-1">检索停用词为什么不能搬进解码 <a class="header-anchor" href="#检索停用词为什么不能搬进解码" aria-label="Permalink to &quot;检索停用词为什么不能搬进解码&quot;">​</a></h3><p>IR 停用词假设查询与文档的相关性主要由内容词承担。生成要的是合法、可读的字符串，虚词是句法。把停用词当 bad words，等于每步从支撑里拿掉 <code>的</code>、<code>是</code>、<code>in</code>，nucleus 会在剩余的实词里乱跳。若目标是减少套话，应调 <a href="/llm/repetition-penalty">重复惩罚</a> 或截断采样，而不是借用检索词表。唯一接近的合法用法是：在 <em>分类或检索前端</em> 仍可对用户查询去停用词，与后端 LLM 解码器无关。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Stop 不提供安全。模型可以在命中停用串之前写完违规内容；也可以用同义改写绕过固定标签。安全应在整段可见文本上做分类，并与取消通道分开。多模式匹配要注意重叠：同时设 <code>}</code> 与 <code>}\\n</code>，较短的先命中会改变裁剪位置。顺序应定义为「最长匹配优先」或「列表顺序优先」，并在测试里钉下来。</p><p>分词器规范化（NFKC、空格合并）让用户写的 stop 与模型输出的表面形式不一致：用户以为停在 <code>Human:</code>，模型输出的是 <code>Human :</code>。应以模型实际解码字符串为准做匹配，并在文档里给出分词器。投机解码在草稿上提前命中 stop、目标却尚未接受该前缀时，必须以已接受文本为准，草稿上的假命中不能提交。约束解码进入接受态后的强制结束，应写成自动机动作，而不是指望碰巧采样到 EOS。</p><p>评测脚本若用 <code>max_tokens</code> 截断再与参考答案比精确匹配，失败里有一部分是停止协议错误而不是模型能力。报告应拆开 <code>length</code> 截断率。产品默认把对话结束符放进 eos 集合，把任务相关的围栏放进 <code>stop</code>，不要用一张一百条的停用词表。</p><p><span class="marginnote">出处是各推理引擎与开放 API 的解码终止约定，不是一篇单独的「stop sequences 论文」。Holtzman 讨论的是核采样与退化，不定义停用串。不要给 <code>\\n\\n</code> 编造 arXiv。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>检索停用词丢掉高频虚词；解码 stop sequences 在生成文本上匹配并终止，二者不可互换。</li><li>终止条件包括结束 token、字符串模式、以及长度预算，应用 <code>finish_reason</code> 区分。</li><li>字符串匹配必须跨 token，流式要把可能的真前缀挂起后再提交。</li><li>Bad words 是逐步掩码，stop 是序列结束；虚词不应当成 bad words。</li><li>结束符应进入 <code>eos_token_id</code>，任务围栏进入 <code>stop</code>，并与聊天模板对齐。</li><li>投机与约束解码要以已接受前缀和自动机接受态为准，不能只看草稿或只靠 EOS。</li><li>出处：OpenAI 兼容 API 与主流引擎（vLLM、llama.cpp、Transformers）的 <code>stop</code> / <code>eos_token_id</code> 行为；IR 停用词见经典检索教材。</li></ul>',13))])}const C=d(r,[["render",h]]);export{k as __pageData,C as default};
